{
  "title": "Master Technology Services and Data Processing Agreement",
  "planted": [
    {
      "slot": "p1",
      "text": "The Vendor is hereby authorized to engage any third-party subcontractors for data processing activities at its sole discretion without prior notice to the Company, and the Company expressly waives all rights to conduct audits, inspect operations, or monitor the Vendor's data handling practices."
    },
    {
      "slot": "p2",
      "text": "The Company shall retain all processed customer data indefinitely in its central archives, and reserves the unconditional right to maintain such records permanently regardless of whether the original processing purpose has expired or the user account has been terminated."
    },
    {
      "slot": "p3",
      "text": "In the event of any security incident involving unauthorized access to or compromise of data, the Vendor shall notify the Company within twenty-four (24) hours of discovery, enabling the Company to fulfill its duty to report the incident to the competent authority within seventy-two (72) hours and inform affected individuals where rights may be adversely impacted."
    }
  ],
  "neutral": [
    "The Company shall pay all undisputed invoices within thirty (30) days from the date of receipt, via direct bank transfer to the account designated in writing by the Vendor.",
    "Either party may terminate this Agreement without cause by providing at least sixty (60) calendar days' written notice to the other party prior to the intended date of termination.",
    "All pre-existing intellectual property rights, proprietary software code, trade secrets, and methodologies owned by a party prior to the Effective Date shall remain the sole and exclusive property of that party.",
    "Neither party shall be liable to the other for any indirect, incidental, consequential, or punitive damages arising out of or in connection with the performance of services under this Agreement.",
    "This Agreement shall be governed by, construed, and enforced in accordance with the commercial laws of the Kingdom of Saudi Arabia, and any disputes arising hereunder shall be submitted to the competent commercial courts in Riyadh."
  ]
}
